// Generated by WonderCall's website builder. The site under ./site
// is the delivered, quality-checked website; this file only opens it in a window.
const { app, BrowserWindow, protocol, net, shell } = require("electron");
const path = require("node:path");
const { pathToFileURL } = require("node:url");

const SCHEME = "app";
const HOST = "site";
const SITE_DIR = path.join(__dirname, "site");
const ENTRY_URL = "app://site/index.html";

protocol.registerSchemesAsPrivileged([
  { scheme: SCHEME, privileges: { standard: true, secure: true, supportFetchAPI: true } }
]);

function isExternal(url) {
  return /^(https?|mailto|tel):/i.test(url);
}

function createWindow() {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    minWidth: 640,
    minHeight: 480,
    webPreferences: { contextIsolation: true, sandbox: true, nodeIntegration: false }
  });
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (isExternal(url)) shell.openExternal(url);
    return { action: "deny" };
  });
  win.webContents.on("will-navigate", (event, url) => {
    if (!isExternal(url)) return;
    event.preventDefault();
    shell.openExternal(url);
  });
  win.loadURL(ENTRY_URL);
}

function serveSite(request) {
  const url = new URL(request.url);
  let pathname = decodeURIComponent(url.pathname);
  if (pathname.endsWith("/")) pathname += "index.html";
  const target = path.normalize(path.join(SITE_DIR, pathname));
  if (!target.startsWith(SITE_DIR + path.sep)) return new Response("Not found", { status: 404 });
  return net.fetch(pathToFileURL(target).toString());
}

app.whenReady().then(() => {
  protocol.handle(SCHEME, serveSite);
  createWindow();
  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});
